ALTER TABLE public.investor_profiles ADD COLUMN IF NOT EXISTS matched_instruments text[] NOT NULL DEFAULT '{}',ADD COLUMN IF NOT EXISTS financing_capabilities text[] NOT NULL DEFAULT '{}',ADD COLUMN IF NOT EXISTS earliest_stage public.project_stage;
UPDATE public.investor_profiles SET matched_instruments=CASE instrument_sought WHEN 'either' THEN ARRAY['equity','equity_and_shareholder_loan','preferred_equity','mezzanine','convertible'] WHEN 'equity' THEN ARRAY['equity'] ELSE '{}' END,financing_capabilities=CASE WHEN instrument_sought='debt' THEN ARRAY['senior_debt'] ELSE '{}' END;
ALTER TABLE public.investor_profiles ADD CONSTRAINT matched_instruments_values CHECK(matched_instruments <@ ARRAY['equity','equity_and_shareholder_loan','preferred_equity','mezzanine','convertible']),ADD CONSTRAINT financing_capabilities_values CHECK(financing_capabilities <@ ARRAY['senior_debt','guarantee_provision','grant_cofinancing']);
COMMENT ON COLUMN public.investor_profiles.instrument_sought IS 'DEPRECATED: profile preferences use matched_instruments and financing_capabilities; historical request evidence is unchanged';
ALTER TABLE public.access_request_answers ADD COLUMN IF NOT EXISTS matched_instruments text[];
ALTER TABLE public.access_request_answers ADD CONSTRAINT request_matched_instruments_values CHECK(matched_instruments <@ ARRAY['equity','equity_and_shareholder_loan','preferred_equity','mezzanine','convertible']);
CREATE OR REPLACE FUNCTION public.lock_matched_request_instruments() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF NEW.matched_instruments IS DISTINCT FROM OLD.matched_instruments THEN RAISE EXCEPTION 'Signed instrument selections are immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER lock_matched_instrument_evidence BEFORE UPDATE ON public.access_request_answers FOR EACH ROW EXECUTE FUNCTION public.lock_matched_request_instruments();